typedef struct {
  bool is_compressed;
  size_t compressed_size;
  uint32_t density;
} page_t;

void handle_fault(page_t *p) {
  if (atomic_load(&p->is_compressed)) {
    decompress_page(p);
  } else {
    // normal load into cache
  }
}
```

